SELECT mm.*
FROM merchant_member mm
LEFT JOIN member m   ON mm.member_id   = m.member_id
LEFT JOIN merchant mc ON mm.merchant_id = mc.merchant_id


        AND mm.role_id = #{roleId}


        AND m.status = #{status}


        AND mm.merchant_id = #{merchantId}


        AND mc.merchant_name LIKE CONCAT('%', #{merchantName}, '%')


        AND m.name LIKE CONCAT('%', #{name}, '%')


        AND m.login_id LIKE CONCAT('%', #{loginId}, '%')


ORDER BY mm.created_at DESC
LIMIT #{size} OFFSET #{offset}

